-- Pagos que el reporte de pagos a proveedores de Finnegans (jul–sep 2026) aplica a facturas que seguían «a reconstruir»:
-- el medio (caja, Mercado Pago, e-cheq o transferencia Galicia, débito) no estaba usado en ninguna OP y los dólares
-- del medio igualan a los de las facturas aplicadas del proveedor. Fuente:
-- ~/Desktop/CADINC-documentos/Finnegans/Pagos a proveedores jul-sep 2026 (tesoreria Finnegans).xlsx
do $m$
declare
  u  uuid := 'a7d0ea6b-0bec-4ac0-bfc8-ef6262743dd8';
  d  jsonb := '[{"prov": 189, "fecha": "2026-09-04", "monto": 430647.29, "lineas": [{"tipo": "factura", "factura_id": 614, "monto": 430647.29}], "forma": "efectivo", "cuenta": 3, "ref": "Finnegans (pagos a proveedores): 04/09 Caja en Pesos ·   $430,647.29"}, {"prov": 99, "fecha": "2026-09-18", "monto": 79300.01, "lineas": [{"tipo": "factura", "factura_id": 932, "monto": 79300.01}], "forma": "transferencia", "cuenta": 1, "ref": "Finnegans (pagos a proveedores): 18/09 Banco Galicia Cta Cte $ · Transferencia a tercero  $79,300.01"}, {"prov": 14, "fecha": "2026-09-04", "monto": 435958.88, "lineas": [{"tipo": "factura", "factura_id": 298, "monto": 99039.6}, {"tipo": "factura", "factura_id": 351, "monto": 186952.53}, {"tipo": "factura", "factura_id": 379, "monto": 145331.56}, {"tipo": "a_cuenta", "monto": 4635.19}], "forma": "echeq", "cuenta": 1, "cheques": [{"numero": "3013", "banco": "Galicia", "fecha_cobro": "2026-09-04", "monto": 435958.88, "es_propio": true, "librador": ""}], "ref": "Finnegans (pagos a proveedores): 04/09 Banco Galicia Cta Cte $ Diferidos · Emisión de cheque propio Diferido ch 3013 $435,958.88"}, {"prov": 65, "fecha": "2026-07-07", "monto": 800000.02, "lineas": [{"tipo": "factura", "factura_id": 114, "monto": 800000.02}], "forma": "efectivo", "cuenta": 3, "ref": "Finnegans (pagos a proveedores): 07/07 Caja en Pesos ·   $800,000.02"}, {"prov": 106, "fecha": "2026-07-27", "monto": 48278.36, "lineas": [{"tipo": "factura", "factura_id": 229, "monto": 48278.36}], "forma": "debito_automatico", "cuenta": 1, "ref": "Finnegans (pagos a proveedores): 27/07 Banco Galicia Cta Cte $ Diferidos · Debito Automatico en Cuenta  $48,278.36"}, {"prov": 183, "fecha": "2026-08-26", "monto": 971.46, "lineas": [{"tipo": "factura", "factura_id": 624, "monto": 971.46}], "forma": "efectivo", "cuenta": 3, "ref": "Finnegans (pagos a proveedores): 26/08 Caja en Pesos ·   $971.46"}, {"prov": 183, "fecha": "2026-09-04", "monto": 272000.0, "lineas": [{"tipo": "factura", "factura_id": 761, "monto": 272000.0}], "forma": "transferencia", "cuenta": 18, "ref": "Finnegans (pagos a proveedores): 04/09 Mercado Pago · Transferencia a tercero  $272,000.00"}, {"prov": 78, "fecha": "2026-09-14", "monto": 442931.35, "lineas": [{"tipo": "factura", "factura_id": 179, "monto": 34447.42}, {"tipo": "factura", "factura_id": 457, "monto": 252500.82}, {"tipo": "factura", "factura_id": 504, "monto": 27415.07}, {"tipo": "factura", "factura_id": 616, "monto": 114260.19}, {"tipo": "factura", "factura_id": 638, "monto": 14307.85}], "forma": "echeq", "cuenta": 1, "cheques": [{"numero": "3041", "banco": "Galicia", "fecha_cobro": "2026-09-14", "monto": 442931.35, "es_propio": true, "librador": ""}], "ref": "Finnegans (pagos a proveedores): 14/09 Banco Galicia Cta Cte $ Diferidos · Emisión de cheque propio Diferido ch 3041 $442,931.35"}, {"prov": 55, "fecha": "2026-09-01", "monto": 283999.99, "lineas": [{"tipo": "factura", "factura_id": 103, "monto": 245999.99}, {"tipo": "factura", "factura_id": 470, "monto": 21000.0}, {"tipo": "factura", "factura_id": 724, "monto": 17000.0}], "forma": "efectivo", "cuenta": 3, "ref": "Finnegans (pagos a proveedores): 01/09 Caja en Pesos ·   $283,999.99"}, {"prov": 55, "fecha": "2026-09-11", "monto": 21000.0, "lineas": [{"tipo": "factura", "factura_id": 716, "monto": 21000.0}], "forma": "efectivo", "cuenta": 3, "ref": "Finnegans (pagos a proveedores): 11/09 Caja en Pesos ·   $21,000.00"}]'::jsonb;
  e  jsonb;
begin
  for e in select * from jsonb_array_elements(d) loop
    perform public.pagos_reconstruir_orden((e->>'prov')::bigint,
      jsonb_build_object('fecha', e->>'fecha', 'forma_pago', e->>'forma', 'monto_pagado', (e->>'monto')::numeric,
        'cuenta_origen_id', (e->>'cuenta')::bigint, 'referencia', e->>'ref',
        'obs', 'Pago reconstruido el 26/09 con el reporte de pagos de Finnegans')
        || case when e ? 'cheques' then jsonb_build_object('cheques', e->'cheques') else '{}'::jsonb end,
      e->'lineas', u);
  end loop;
end $m$;
